    24	/** POST /api/chat/:agentId — streams an AI SDK v7 UI message stream (SSE). */
    25	export async function handleChat(
    26	  agentKeyOrId: string,
    27	  req: http.IncomingMessage,
    28	  res: http.ServerResponse,
    29	): Promise<void> {
    30	  if (req.method !== "POST") {
    31	    res.writeHead(405, { allow: "POST" }).end();
    32	    return;
    33	  }
    34	  const agentId = resolveAgentId(agentKeyOrId);
    35	  if (!agentId) {
    36	    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
    37	    return;
    38	  }
    39	
    40	  let messages: UIMessage[];
    41	  try {
    42	    const body = JSON.parse(await readBody(req)) as { messages?: unknown };
    43	    if (!Array.isArray(body?.messages) || body.messages.length === 0) throw new Error("messages required");
    44	    messages = body.messages as UIMessage[];
    45	  } catch (error) {
    46	    const tooLarge = error instanceof BodyTooLargeError;
    47	    sendJson(res, tooLarge ? 413 : 400, {
    48	      error: tooLarge ? "Request body too large" : "Expected JSON body with a non-empty messages array",
    49	    });
    50	    return;
    51	  }
    52	
    53	  // Stop generation when the browser disconnects.
    54	  const abort = new AbortController();
    55	  res.on("close", () => {
    56	    if (!res.writableFinished) abort.abort();
    57	  });
    58	
    59	  // Only `messages` is taken from the client: other AgentExecutionOptions (instructions,
    60	  // maxSteps, tools...) must not be client-controlled.
    61	  const stream = await handleChatStream({
    62	    mastra,
    63	    agentId,
    64	    version: "v7",
    65	    params: { messages, abortSignal: abort.signal },
    66	    onError: (error) => {
    67	      console.error("Web chat stream failed", { agentId, error });
    68	      return "Sorry, something went wrong while generating a reply.";
    69	    },
    70	  });
