    72	
    73	  res.writeHead(response.status, Object.fromEntries(response.headers));
    74	  res.flushHeaders();
    75	  if (!response.body) {
    76	    res.end();
    77	    return;
    78	  }
    79	  try {
    80	    for await (const chunk of response.body) {
    81	      if (abort.signal.aborted) break;
    82	      res.write(chunk);
    83	    }
    84	  } finally {
    85	    res.end();
    86	  }
    87	}
